mapper.select:


    del_flag = '0'
     AND abnormal_no LIKE CONCAT('%', #{abnormal_no}, '%')
     AND work_order_no LIKE CONCAT('%', #{work_order_no}, '%')
     AND abnormal_type = #{abnormal_type}
     AND severity = #{severity}
     AND status = #{status}
     AND report_by LIKE CONCAT('%', #{report_by}, '%')
     AND date(create_time) >= #{params.beginTime}
     AND date(create_time) <= #{params.endTime}

ORDER BY abnormal_id DESC
